// Security+ Quest: question bank, acronyms and ports.
// Organized by the five CompTIA Security+ (SY0-701) exam domains, plus an AI bonus zone.
// In every question, a[0] is the correct answer; the game shuffles options at runtime.
const DOMAINS=[
{id:1,name:"General Security Concepts",zone:"The Foundry",weight:"12%",color:"#5ee6ff",enemies:["Misconfig Mite","Weak-Key Wisp","Cert Phantom"],boss:"The Unpatched Archon"},
{id:2,name:"Threats, Vulnerabilities & Mitigations",zone:"The Badlands",weight:"22%",color:"#ff5c8a",enemies:["Phishling","Ransom Golem","Worm Wyrm"],boss:"The Ransom Baron"},
{id:3,name:"Security Architecture",zone:"Cloud Citadel",weight:"18%",color:"#a98bff",enemies:["Drift Daemon","Flat-Net Hydra","Single-Point Specter"],boss:"The Outage Titan"},
{id:4,name:"Security Operations",zone:"The SOC Depths",weight:"28%",color:"#3dff9a",enemies:["Alert Swarm","Stale Account Shade","Log Gap Goblin"],boss:"Ghost Operator"},
{id:5,name:"Security Program Management & Oversight",zone:"Governance Spire",weight:"20%",color:"#ffc94d",enemies:["Shadow Vendor","Audit Wraith","Policy Gremlin"],boss:"The Rogue Sysadmin"},
{id:6,name:"Bonus: AI Security",zone:"The Neural Rift",weight:"Bonus",color:"#ff9b4d",enemies:["Prompt Imp","Poisoned Dataset"],boss:"Rogue Model"}
];

// a[0] is always the correct answer; options are shuffled at runtime.
const Q=[
// ---------- Domain 1 ----------
{d:1,q:"Concrete bollards in front of a data center entrance are an example of which control category?",a:["Physical","Technical","Managerial","Operational"],e:"Bollards are a physical control: tangible barriers that stop vehicles from reaching a building."},
{d:1,q:"A login banner warning that unauthorized access will be prosecuted is primarily which control type?",a:["Deterrent","Detective","Corrective","Compensating"],e:"Deterrent controls discourage an attacker from trying. The banner doesn't block or detect anything itself."},
{d:1,q:"After a ransomware infection, the team restores servers from clean backups. Which control type is the restore?",a:["Corrective","Preventive","Deterrent","Directive"],e:"Corrective controls fix or reverse damage after an incident has happened."},
{d:1,q:"A legacy system can't support MFA, so the team isolates it on its own VLAN and adds extra monitoring. What kind of control is this?",a:["Compensating","Directive","Deterrent","Preventive"],e:"A compensating control is an alternative measure used when the primary control can't be implemented."},
{d:1,q:"A written policy requiring annual risk assessments falls into which control category?",a:["Managerial","Technical","Physical","Operational"],e:"Managerial (administrative) controls are policies, procedures and risk-management activities set by leadership."},
{d:1,q:"Reviewing firewall logs each morning to spot suspicious activity is which control type?",a:["Detective","Preventive","Deterrent","Corrective"],e:"Detective controls identify that something happened (log review, IDS alerts, cameras being monitored)."},
{d:1,q:"Comparing a file's hash today with the hash recorded last week verifies which part of the CIA triad?",a:["Integrity","Confidentiality","Availability","Authorization"],e:"Hashes detect changes, so they verify integrity: the data hasn't been altered."},
{d:1,q:"Which mechanism provides non-repudiation, so a sender can't later deny sending a message?",a:["A digital signature","Symmetric encryption","A load balancer","Data masking"],e:"A digital signature is made with the sender's private key, which only they hold, proving origin and integrity."},
{d:1,q:"In the AAA framework, recording which files a user opened and when is called:",a:["Accounting","Authentication","Authorization","Attestation"],e:"Accounting tracks what users actually did: logs of resource use and activity."},
{d:1,q:"In a Zero Trust architecture, which component makes the decision to grant or deny access?",a:["Policy Engine","Policy Enforcement Point","Implicit trust zone","Subject"],e:"The Policy Engine decides, the Policy Administrator relays the decision, and the Policy Enforcement Point applies it."},
{d:1,q:"Zero Trust divides its functions into which two planes?",a:["Control plane and data plane","Management plane and user plane","Physical plane and logical plane","Trust plane and threat plane"],e:"The control plane makes policy decisions (adaptive identity, policy engine); the data plane carries traffic and enforces decisions."},
{d:1,q:"An analyst compares the company's current controls with a framework to see what's missing. This is a:",a:["Gap analysis","Penetration test","Tabletop exercise","Root cause analysis"],e:"A gap analysis measures the difference between where you are and where you need to be."},
{d:1,q:"A fake 'admin' credential is planted in a database. If anyone ever uses it, the team knows the data was stolen. This is a:",a:["Honeytoken","Honeynet","Honeypot","DNS sinkhole"],e:"A honeytoken is fake data used as a tripwire. A honeypot is a fake system; a honeynet is a network of them."},
{d:1,q:"In change management, the purpose of a backout plan is to:",a:["Restore the previous state if the change fails","Notify stakeholders of the change","Get approval from the change board","Schedule the change in a maintenance window"],e:"A backout (rollback) plan returns systems to a known-good state if the change causes problems."},
{d:1,q:"Why are changes usually made during a scheduled maintenance window?",a:["To minimize impact on users and business operations","To avoid needing approval","Because logging is disabled then","So testing can be skipped"],e:"Maintenance windows are agreed low-impact periods, reducing disruption if something goes wrong."},
{d:1,q:"Which of these is a symmetric encryption algorithm?",a:["AES","RSA","ECC","Diffie-Hellman"],e:"AES uses one shared key for encryption and decryption. RSA and ECC are asymmetric; Diffie-Hellman is a key-exchange method."},
{d:1,q:"Alice wants to send Bob a message only Bob can read. Which key does she encrypt it with?",a:["Bob's public key","Bob's private key","Alice's private key","Alice's public key"],e:"Encrypt with the recipient's public key; only the recipient's private key can decrypt it."},
{d:1,q:"A digital signature is created by encrypting a hash of the message with:",a:["The sender's private key","The sender's public key","The recipient's public key","A shared session key"],e:"The sender signs with their private key; anyone can verify with the sender's public key."},
{d:1,q:"Adding a random value to each password before hashing mainly defends against:",a:["Rainbow table attacks","Phishing","On-path attacks","Replay attacks"],e:"Salting makes every hash unique, so precomputed rainbow tables don't work."},
{d:1,q:"PBKDF2 and bcrypt make password hashes harder to brute-force by:",a:["Key stretching: running the hash many times","Splitting keys between custodians","Compressing the password","Encrypting with a public key"],e:"Key stretching deliberately slows hashing so each guess costs an attacker far more time."},
{d:1,q:"Which method checks one certificate's revocation status in real time, instead of downloading a full list?",a:["OCSP","CRL","CSR","PEM"],e:"OCSP queries the CA about a single certificate. A CRL is a whole list downloaded periodically. OCSP stapling lets the server attach the response itself."},
{d:1,q:"A single certificate for *.example.com that covers www, mail and shop subdomains is a:",a:["Wildcard certificate","Self-signed certificate","Root certificate","Code-signing certificate"],e:"A wildcard certificate secures all first-level subdomains of a domain."},
{d:1,q:"To get a certificate from a CA, an admin generates a key pair and submits a:",a:["Certificate Signing Request (CSR)","Certificate Revocation List (CRL)","OCSP response","Key escrow request"],e:"The CSR contains the public key and identifying details; the CA signs it to issue the certificate."},
{d:1,q:"A chip on a laptop's motherboard stores disk-encryption keys and checks boot integrity. This is a:",a:["TPM","HSM","Key escrow agent","Certificate authority"],e:"A Trusted Platform Module is built into the device. An HSM is a dedicated appliance for managing many keys at scale."},
{d:1,q:"A bank needs tamper-resistant hardware to generate and protect thousands of keys for its servers. Best choice?",a:["HSM","TPM","USB flash drive","Self-encrypting drive"],e:"Hardware Security Modules are built for high-volume, high-assurance key generation and storage."},
{d:1,q:"Replacing a card number with a random value that maps back to the real number only in a secure vault is:",a:["Tokenization","Masking","Hashing","Steganography"],e:"Tokenization substitutes a token and keeps the mapping elsewhere. Masking just hides part of the data (****1234)."},
{d:1,q:"Hiding secret data inside the pixels of an ordinary image is:",a:["Steganography","Salting","Tokenization","Key stretching"],e:"Steganography conceals the very existence of data inside innocent-looking data."},
{d:1,q:"A trusted third party holds copies of encryption keys so data can be recovered if keys are lost. This is:",a:["Key escrow","Key stretching","Key exchange","Certificate pinning"],e:"Key escrow stores keys with a trusted party for recovery."},
{d:1,q:"Which physical control is specifically designed to stop tailgating?",a:["Access control vestibule","Bollards","Lighting","Fencing"],e:"An access control vestibule (formerly 'mantrap') lets one person through at a time between two doors."},
{d:1,q:"A distributed, tamper-evident record of transactions that anyone can verify is a(n):",a:["Open public ledger (blockchain)","Certificate revocation list","Key escrow","Rainbow table"],e:"Blockchain is an open public ledger; each block links to the previous one by hash."},
{d:1,q:"Using temporary session keys so a stolen server key can't decrypt past sessions is called:",a:["Perfect forward secrecy","Key escrow","Certificate pinning","Salting"],e:"Perfect forward secrecy creates unique ephemeral keys for each session."},
{d:1,q:"A company issues its own certificate for an internal test server without any outside CA. This is a:",a:["Self-signed certificate","Wildcard certificate","Third-party certificate","Extended validation certificate"],e:"Self-signed certificates aren't trusted by default outside the organization but work for internal use."},
// ---------- Domain 2 ----------
{d:2,q:"A well-funded group spends months quietly inside a defense contractor's network stealing designs. The most likely actor is:",a:["Nation-state","Unskilled attacker","Hacktivist","Lone insider"],e:"Nation-states have large resources and patience and are associated with APTs focused on espionage."},
{d:2,q:"A group defaces a company's website to protest its environmental record. Actor and motivation?",a:["Hacktivist; philosophical/political belief","Organized crime; financial gain","Nation-state; espionage","Insider; revenge"],e:"Hacktivists act out of ideological or political motivation."},
{d:2,q:"Employees sign up for an unapproved file-sharing service to work faster. This is:",a:["Shadow IT","An insider attack","A supply chain compromise","Typosquatting"],e:"Shadow IT is technology used without IT/security approval, creating unmanaged risk."},
{d:2,q:"Someone runs a downloaded attack tool without understanding how it works. This actor is best described as:",a:["Unskilled attacker","Nation-state","APT","Organized crime"],e:"Unskilled attackers rely on other people's tools and have low sophistication."},
{d:2,q:"A text message says your bank account is locked and links to a login page. This is:",a:["Smishing","Vishing","Whaling","Bluejacking"],e:"Smishing = SMS phishing. Vishing is phishing by voice call."},
{d:2,q:"An attacker phones the help desk pretending to be the CFO to get a password reset. This is:",a:["Vishing","Smishing","Watering hole attack","Typosquatting"],e:"Vishing is voice phishing; impersonating an authority figure adds pressure."},
{d:2,q:"A phishing campaign aimed specifically at a company's CEO and board is called:",a:["Whaling","Spam","Smishing","Pharming"],e:"Whaling targets high-value executives."},
{d:2,q:"Attackers compromise a niche industry forum they know the target's engineers visit. This is a:",a:["Watering hole attack","Typosquatting attack","Evil twin attack","Replay attack"],e:"A watering hole attack infects a site the target group already trusts and visits."},
{d:2,q:"An attacker registers 'rnicrosoft.com' hoping users won't notice it isn't the real domain. This is:",a:["Typosquatting","Pretexting","Vishing","Replay attack"],e:"Typosquatting (URL hijacking) relies on typos and look-alike names."},
{d:2,q:"An attacker invents a believable story ('I'm from IT, auditing your mailbox') to get information. This technique is:",a:["Pretexting","Tailgating","Shoulder surfing","Watering hole"],e:"Pretexting is building a fabricated scenario to manipulate the victim."},
{d:2,q:"An email that seems to come from a real vendor asks accounts payable to update bank details for an invoice. This is:",a:["Business email compromise","Smishing","Bluejacking","A logic bomb"],e:"BEC uses compromised or spoofed business email to redirect payments."},
{d:2,q:"Attackers breach a managed service provider and use its remote tools to hit all of its clients. This is a:",a:["Supply chain attack","Watering hole attack","Insider threat","Zero-day exploit"],e:"Attacking a trusted supplier or MSP to reach its customers is a supply chain attack."},
{d:2,q:"A login form accepts the input ' OR 1=1 -- and logs the attacker in. What attack is it, and the best fix?",a:["SQL injection; parameterized queries","XSS; output encoding","Buffer overflow; DEP","CSRF; anti-CSRF tokens"],e:"SQL injection alters database queries. Parameterized queries (prepared statements) and input validation stop it."},
{d:2,q:"An attacker posts a comment containing a script that runs in every visitor's browser. This is:",a:["Cross-site scripting (XSS)","SQL injection","Directory traversal","Race condition"],e:"XSS injects client-side script into pages other users view."},
{d:2,q:"A web page makes a logged-in user's browser silently submit a funds-transfer request to their bank. This is:",a:["Cross-site request forgery (CSRF)","Cross-site scripting (XSS)","SQL injection","Directory traversal"],e:"CSRF abuses the trust a site places in the user's authenticated browser. Anti-CSRF tokens help prevent it."},
{d:2,q:"A program writes more data into a memory area than it can hold, overwriting neighboring memory. This is a:",a:["Buffer overflow","Race condition","Replay attack","Downgrade attack"],e:"Buffer overflows can let attackers overwrite return addresses and run their own code."},
{d:2,q:"A file's permissions are checked, then an attacker swaps the file before it's used. This is a:",a:["Time-of-check to time-of-use (TOCTOU) race condition","Buffer overflow","Directory traversal","Downgrade attack"],e:"TOCTOU exploits the gap between checking a resource and using it."},
{d:2,q:"A web request containing ../../../etc/passwd is attempting:",a:["Directory traversal","SQL injection","Cross-site scripting","Privilege escalation via sudo"],e:"Directory (path) traversal uses ../ to escape the web root and read other files."},
{d:2,q:"Files on a network share suddenly get a new extension and a note demands cryptocurrency. This is:",a:["Ransomware","A logic bomb","Spyware","A rootkit"],e:"Ransomware encrypts data and demands payment for the key."},
{d:2,q:"Code planted by a former admin deletes payroll records on a specific date. This is a:",a:["Logic bomb","Worm","Trojan","Keylogger"],e:"A logic bomb fires when a condition is met, such as a date or event."},
{d:2,q:"Malware that hides deep in the operating system kernel and conceals itself from antivirus is a:",a:["Rootkit","Keylogger","Bloatware","Adware"],e:"Rootkits modify the OS to hide their presence and keep privileged access."},
{d:2,q:"Malware spreads from computer to computer across a network with no user action. It's a:",a:["Worm","Virus","Trojan","Logic bomb"],e:"Worms self-replicate across networks. Viruses usually need a user to run an infected file."},
{d:2,q:"A free 'PDF converter' secretly installs a backdoor for remote control. This is a:",a:["Trojan (RAT)","Worm","Logic bomb","Bloatware"],e:"A Trojan pretends to be legitimate software. A remote access Trojan (RAT) gives the attacker control."},
{d:2,q:"Malware that records every key a user types is a:",a:["Keylogger","Rootkit","Worm","Logic bomb"],e:"Keyloggers capture keystrokes to steal passwords and other data."},
{d:2,q:"An attacker tries 'Winter2026!' once against every account in the company. This is:",a:["Password spraying","Brute force","Rainbow table attack","Birthday attack"],e:"Spraying tries a few common passwords across many accounts, staying under lockout thresholds."},
{d:2,q:"An attacker on public Wi-Fi intercepts and alters traffic between a user and a website. This is:",a:["On-path attack","Replay attack","DDoS","Bluesnarfing"],e:"An on-path (formerly man-in-the-middle) attacker sits between two parties."},
{d:2,q:"An attacker captures a valid authentication exchange and sends it again later to log in. This is a:",a:["Replay attack","Downgrade attack","Birthday attack","Directory traversal"],e:"Replay attacks reuse captured valid data. Timestamps, nonces and session tokens help prevent them."},
{d:2,q:"Small spoofed DNS queries trigger huge responses aimed at a victim. This is:",a:["Reflected, amplified DDoS","SQL injection","DNS sinkholing","Replay attack"],e:"Reflection plus amplification uses third-party servers to multiply traffic toward the victim."},
{d:2,q:"An attacker forces a connection to fall back from TLS 1.3 to an older, weaker protocol. This is a:",a:["Downgrade attack","Replay attack","Collision attack","Privilege escalation"],e:"Downgrade attacks force weaker protocols or ciphers. SSL stripping is one example."},
{d:2,q:"Finding two different inputs that produce the same hash is the goal of a:",a:["Birthday (collision) attack","Rainbow table attack","Password spraying attack","Replay attack"],e:"Birthday attacks use probability to find hash collisions."},
{d:2,q:"A standard user exploits a flaw to gain administrator rights. This is:",a:["Privilege escalation","Lateral movement","Pivoting","Sideloading"],e:"Privilege escalation raises access beyond what was granted. Lateral movement is moving to other systems."},
{d:2,q:"A vulnerability exploited before the vendor knows about it or has a patch is a:",a:["Zero-day","Legacy vulnerability","Misconfiguration","False positive"],e:"Zero-days have no fix available when they're exploited."},
{d:2,q:"A user installs apps on their phone from outside the official app store. This is:",a:["Sideloading","Jailbreaking","Bluejacking","Smishing"],e:"Sideloading installs apps from unofficial sources. Jailbreaking/rooting removes OS restrictions."},
{d:2,q:"A user logs in from New York and, ten minutes later, from Singapore. This indicator is:",a:["Impossible travel","Resource consumption","Out-of-cycle logging","Blocked content"],e:"Impossible travel suggests stolen credentials being used somewhere else."},
{d:2,q:"Malicious code inside a virtual machine breaks out to reach the hypervisor. This is:",a:["VM escape","Resource reuse","Sideloading","Directory traversal"],e:"VM escape lets an attacker get from a guest to the host or other VMs."},
{d:2,q:"An attacker sets up an access point with the same network name as the coffee shop's Wi-Fi. This is a(n):",a:["Evil twin","Bluesnarfing attack","Jamming attack","Replay attack"],e:"An evil twin impersonates a legitimate access point to intercept traffic."},
{d:2,q:"Data is stolen from a phone over Bluetooth without the owner knowing. This is:",a:["Bluesnarfing","Bluejacking","Smishing","War driving"],e:"Bluesnarfing steals data. Bluejacking only sends unsolicited messages."},
{d:2,q:"A new IoT camera is deployed still using its factory admin/admin login. The vulnerability is:",a:["Default credentials (misconfiguration)","Zero-day","Race condition","Firmware rootkit"],e:"Unchanged defaults are a classic misconfiguration; change them during hardening."},
{d:2,q:"Which mitigation best stops unapproved software from running on workstations?",a:["Application allow list","Port mirroring","Data masking","Load balancing"],e:"An allow list only permits approved applications to run."},
{d:2,q:"Splitting a network so a compromised guest laptop can't reach the payroll server is:",a:["Segmentation","Encryption","Decommissioning","Patching"],e:"Segmentation limits how far an attacker can move."},
{d:2,q:"Many failed logins followed by locked accounts is an indicator of:",a:["Brute-force or guessing attempts","Data exfiltration","Missing logs","A logic bomb"],e:"Account lockouts commonly follow brute-force or password-guessing attacks."},
{d:2,q:"Logs show gaps exactly during the time an attacker was active. This indicator is:",a:["Missing logs","Impossible travel","Concurrent session usage","Blocked content"],e:"Attackers often delete or stop logs to hide their tracks; missing logs are a red flag."},
// ---------- Domain 3 ----------
{d:3,q:"In an IaaS cloud deployment, who patches the guest operating system?",a:["The customer","The cloud provider","The hypervisor vendor","Nobody: it's automatic"],e:"Shared responsibility: in IaaS the provider secures hardware and hypervisor; the customer manages the OS, apps and data."},
{d:3,q:"With SaaS, the customer is still typically responsible for:",a:["Their data and who can access it","Patching the application","Physical data center security","The underlying operating system"],e:"In SaaS the provider runs almost everything, but customers manage their users and the data they put in."},
{d:3,q:"Defining servers and networks in version-controlled template files is called:",a:["Infrastructure as code","Serverless","Containerization","Microservices"],e:"IaC makes deployments repeatable and consistent, reducing configuration drift."},
{d:3,q:"Running code as functions with no servers for the customer to manage is:",a:["Serverless","IaaS","On-premises","Air-gapped"],e:"Serverless moves server management to the provider; you deploy functions."},
{d:3,q:"An app built as many small independent services that talk via APIs uses a:",a:["Microservices architecture","Monolithic architecture","Air-gapped design","Mainframe model"],e:"Microservices scale and fail independently but increase the number of APIs to secure."},
{d:3,q:"Software-defined networking (SDN) separates which two planes?",a:["Control plane and data plane","Physical plane and virtual plane","User plane and kernel plane","Trust plane and DMZ plane"],e:"SDN centralizes the control plane (decisions) apart from the data plane (forwarding)."},
{d:3,q:"A network with no physical or wireless connection to any other network is:",a:["Air-gapped","Segmented with VLANs","A screened subnet","Behind NAT"],e:"An air gap is complete physical isolation."},
{d:3,q:"Why are ICS/SCADA systems hard to secure?",a:["They often can't be patched or taken offline easily","They never use networks","They only run modern operating systems","They have no physical components"],e:"Industrial systems run critical processes around the clock on legacy tech; segmentation is a key protection."},
{d:3,q:"A backup site with power, network and fully configured systems, ready within minutes or hours, is a:",a:["Hot site","Warm site","Cold site","Tape vault"],e:"Hot: ready to go. Warm: some equipment, needs setup. Cold: space and power only."},
{d:3,q:"The maximum acceptable time to restore a service after an outage is the:",a:["Recovery Time Objective (RTO)","Recovery Point Objective (RPO)","Mean Time Between Failures (MTBF)","Annualized Rate of Occurrence (ARO)"],e:"RTO is how long you can be down. RPO is how much data, measured in time, you can afford to lose."},
{d:3,q:"Backups run every 4 hours, so up to 4 hours of data could be lost. That 4 hours relates to the:",a:["RPO","RTO","MTTR","SLA"],e:"Recovery Point Objective = maximum tolerable data loss."},
{d:3,q:"The average time it takes to repair a failed component is the:",a:["MTTR","MTBF","RTO","RPO"],e:"Mean Time To Repair. MTBF (Mean Time Between Failures) measures reliability."},
{d:3,q:"Which backup copies all data changed since the last FULL backup, so a restore needs the full plus only the latest one?",a:["Differential","Incremental","Snapshot","Journaling"],e:"Differential grows until the next full. Incremental copies changes since the last backup of any type, so a restore needs the full plus every incremental."},
{d:3,q:"Two servers both handle live traffic, and if one fails the other carries the load. This is:",a:["Active/active load balancing","A cold standby","Air-gapping","Tape rotation"],e:"Active/active spreads load across all nodes and provides high availability."},
{d:3,q:"What provides short-term power during an outage until a generator starts?",a:["UPS","PDU","RAID","Surge protector"],e:"An uninterruptible power supply (battery) bridges the gap; generators provide long-term power."},
{d:3,q:"Data collected in a country being subject to that country's laws is the concept of:",a:["Data sovereignty","Data masking","Data minimization","Tokenization"],e:"Data sovereignty means data is governed by the laws where it's collected or stored."},
{d:3,q:"Data being processed in RAM by an application is in which state?",a:["In use","At rest","In transit","Archived"],e:"Three states: at rest (stored), in transit (moving over a network), in use (being processed)."},
{d:3,q:"Admins connect first to one hardened server, and from it reach internal servers. That server is a:",a:["Jump server","Reverse proxy","Honeypot","Load balancer"],e:"A jump server (jump box) is a controlled entry point into a secure zone."},
{d:3,q:"A device in front of web servers that receives client requests, hides the servers and can filter or cache is a:",a:["Reverse proxy","Forward proxy","Jump server","Layer 2 switch"],e:"Reverse proxies protect servers. Forward proxies act on behalf of internal users going out."},
{d:3,q:"Which device best protects a web application from SQL injection and XSS at Layer 7?",a:["Web application firewall (WAF)","Router ACL","Network tap","UPS"],e:"A WAF inspects HTTP traffic for application-layer attacks."},
{d:3,q:"A firewall that identifies traffic by application, not just port and IP, is a:",a:["Next-generation firewall (NGFW)","Stateless packet filter","Hub","Network tap"],e:"NGFWs are application-aware and often include IPS and other features."},
{d:3,q:"A security appliance is configured so that if it fails, all traffic is blocked. This is:",a:["Fail-closed","Fail-open","Active/passive","Port mirroring"],e:"Fail-closed favors security; fail-open favors availability."},
{d:3,q:"Which device must be placed inline to actively block attacks?",a:["IPS","IDS on a mirrored port","Network tap","SIEM"],e:"An IPS sits inline and can drop traffic. An IDS watches a copy of traffic and alerts."},
{d:3,q:"Which IPsec mode encrypts the entire original packet, headers included, for site-to-site VPNs?",a:["Tunnel mode","Transport mode","AH-only mode","Split mode"],e:"Tunnel mode wraps the whole packet in a new one. Transport mode encrypts only the payload."},
{d:3,q:"Which IPsec protocol provides encryption, not just integrity?",a:["ESP","AH","GRE","ARP"],e:"Encapsulating Security Payload encrypts. Authentication Header gives integrity and authentication only."},
{d:3,q:"A cloud-delivered service that combines SD-WAN with security such as CASB, secure web gateway and zero-trust access is:",a:["SASE","SCADA","SDN","SED"],e:"Secure Access Service Edge converges networking and security in the cloud."},
{d:3,q:"Port-based network access control that requires devices to authenticate before joining the network is:",a:["802.1X","802.11ac","Spanning Tree","VLAN trunking"],e:"802.1X uses EAP with an authentication server, usually RADIUS."},
{d:3,q:"A network zone holding public-facing servers, separated from the internal LAN, is a:",a:["Screened subnet (DMZ)","Air gap","Native VLAN","Intranet"],e:"The screened subnet lets the internet reach public services without reaching the internal network."},
{d:3,q:"The team talks through a simulated ransomware scenario around a table without touching any systems. This is a:",a:["Tabletop exercise","Failover test","Parallel processing test","Penetration test"],e:"Tabletops are discussion-based; failover and simulation tests actually exercise systems."},
{d:3,q:"Capacity planning for resilience considers which three areas?",a:["People, technology and infrastructure","Hot, warm and cold","Confidentiality, integrity and availability","Policies, standards and procedures"],e:"You need enough staff, technology and infrastructure to handle demand and disruption."},
{d:3,q:"Packaging an app with its dependencies so it runs the same anywhere, sharing the host's kernel, is:",a:["Containerization","Full virtualization","Air-gapping","Serverless"],e:"Containers are lightweight and share the host OS kernel, unlike VMs that each run a full OS."},
{d:3,q:"Real-time operating systems (RTOS) are typically found in:",a:["Embedded systems with strict timing needs","Office laptops","SaaS email","Web browsers"],e:"RTOS run embedded and industrial devices where responses must be predictable."},
{d:3,q:"Labeling data 'Public', 'Confidential' or 'Restricted' is an example of:",a:["Data classification","Data sovereignty","Tokenization","Geofencing"],e:"Classification labels data by sensitivity to decide how it must be protected."},
{d:3,q:"Restricting access to a system so it only works from approved countries is:",a:["Geographic restriction","Tokenization","Air-gapping","Journaling"],e:"Geographic restrictions (geolocation/geofencing) limit access by location."},
// ---------- Domain 4 ----------
{d:4,q:"Which is a core step in hardening a new server?",a:["Disable unneeded services and change default passwords","Open all ports for flexibility","Install every available application","Turn off logging to save space"],e:"Hardening shrinks the attack surface: remove what you don't need and lock down what you keep."},
{d:4,q:"A company buys and owns phones but lets employees use them personally too. This model is:",a:["COPE","BYOD","CYOD","VDI"],e:"Corporate-Owned, Personally Enabled. BYOD = employee owns. CYOD = employee chooses from approved company devices."},
{d:4,q:"What lets IT enforce passcodes, push apps and remotely wipe lost phones?",a:["MDM","DLP","SIEM","NAC"],e:"Mobile Device Management centrally manages and secures mobile devices."},
{d:4,q:"WPA3-Personal replaces the pre-shared key handshake with:",a:["SAE (Simultaneous Authentication of Equals)","WEP","TKIP","WPS"],e:"SAE resists offline dictionary attacks against the Wi-Fi passphrase."},
{d:4,q:"Enterprise Wi-Fi where each user signs in with their own credentials typically uses:",a:["802.1X with a RADIUS server","One shared PSK","A WPS PIN","MAC filtering alone"],e:"WPA2/WPA3-Enterprise uses 802.1X/EAP with RADIUS."},
{d:4,q:"Signing software so users can verify who made it and that it wasn't modified is:",a:["Code signing","Sandboxing","Fuzzing","Static analysis"],e:"Code signing uses a certificate to prove origin and integrity."},
{d:4,q:"Reviewing source code for flaws without running it is:",a:["Static code analysis","Dynamic analysis","Fuzzing","Penetration testing"],e:"Static analysis examines code at rest; dynamic analysis tests the running application."},
{d:4,q:"Before disposing of old drives, the company wants proof the data is gone. It should get:",a:["A certificate of destruction/sanitization","A risk register entry","An MOU","A CSR"],e:"A certificate documents that sanitization or destruction was completed."},
{d:4,q:"A vulnerability scan that logs in with an account to inspect configuration in depth is a:",a:["Credentialed scan","Non-credentialed scan","Passive scan","Ping sweep"],e:"Credentialed scans see more (patch levels, settings) and produce fewer false positives."},
{d:4,q:"The scanner reports a vulnerability that, on inspection, doesn't actually exist. This is a:",a:["False positive","False negative","True positive","True negative"],e:"False positive = alert with no real issue. False negative = real issue missed, which is more dangerous."},
{d:4,q:"Which system gives vulnerabilities a 0-10 severity score to help prioritize them?",a:["CVSS","CVE","SPF","NIST CSF"],e:"CVSS scores severity. CVE gives each publicly known vulnerability a unique ID."},
{d:4,q:"After patching a vulnerability, how should the team validate the fix?",a:["Rescan the system","Close the ticket immediately","Disable logging","Accept the risk"],e:"Validating remediation includes rescanning, audits and verification."},
{d:4,q:"Which tool collects logs from many sources, correlates events and raises alerts?",a:["SIEM","DLP","MDM","WAF"],e:"Security Information and Event Management centralizes and correlates logs."},
{d:4,q:"Automating repetitive phishing triage with playbooks is a job for:",a:["SOAR","CVSS","UPS","NetFlow"],e:"Security Orchestration, Automation and Response runs playbooks to automate response."},
{d:4,q:"A tool spots an employee uploading customer SSNs to personal cloud storage and blocks it. This is:",a:["DLP","IDS","NAC","SPF"],e:"Data Loss Prevention detects and blocks sensitive data leaving the organization."},
{d:4,q:"Which DNS record lists the mail servers allowed to send email for a domain?",a:["SPF","DKIM","DMARC","PTR"],e:"SPF lists authorized senders. DKIM signs messages. DMARC tells receivers what to do when checks fail and enables reporting."},
{d:4,q:"Which email control signs outgoing messages so receivers can verify them with a key published in DNS?",a:["DKIM","SPF","DMARC","POP3S"],e:"DomainKeys Identified Mail signs messages with the domain's private key."},
{d:4,q:"Which email standard tells receivers to quarantine or reject mail that fails SPF/DKIM?",a:["DMARC","SPF","DKIM","IMAP"],e:"DMARC sets the policy and provides reporting."},
{d:4,q:"Detecting unauthorized changes to critical system files is the job of:",a:["File integrity monitoring (FIM)","DLP","A load balancer","NetFlow"],e:"FIM alerts when monitored files change."},
{d:4,q:"An agent on laptops records behavior, detects threats and can isolate a host automatically. This is:",a:["EDR","DLP","NAC","SPF"],e:"Endpoint Detection and Response. XDR extends this across network, cloud and email."},
{d:4,q:"What does the 'implicit deny' at the end of a firewall rule set do?",a:["Blocks any traffic not explicitly allowed","Allows all remaining traffic","Logs but allows traffic","Encrypts denied traffic"],e:"If no rule matches, the traffic is denied."},
{d:4,q:"A user changes departments and keeps their old access, piling up rights over time. This is:",a:["Privilege creep","Least privilege","Separation of duties","Federation"],e:"Regular access reviews and proper re-provisioning prevent privilege creep."},
{d:4,q:"Users sign in once to access many web apps. Which XML-based standard often carries the authentication between identity provider and app?",a:["SAML","OAuth","LDAP","RADIUS"],e:"SAML exchanges authentication assertions for browser-based SSO."},
{d:4,q:"An app asks 'Allow access to your calendar?' without ever seeing your password. This uses:",a:["OAuth","SAML","Kerberos","TACACS+"],e:"OAuth is an authorization framework that grants limited access through tokens."},
{d:4,q:"Which pair is true multifactor authentication?",a:["Password + fingerprint","Password + PIN","Fingerprint + face scan","Security question + password"],e:"MFA needs different categories: something you know, have, are, or somewhere you are."},
{d:4,q:"Granting admin rights only for the hour they're needed, then revoking them automatically, is:",a:["Just-in-time permissions","Password spraying","Federation","Discretionary access control"],e:"JIT access is part of privileged access management (PAM), along with password vaulting and ephemeral credentials."},
{d:4,q:"Access based on labels such as 'Secret' and 'Top Secret' that users can't change describes:",a:["Mandatory Access Control (MAC)","Discretionary Access Control (DAC)","Role-based access control","Rule-based access control"],e:"In MAC the system enforces labels and clearances. In DAC the data owner decides."},
{d:4,q:"Access granted based on department, device type, location and time of day is:",a:["Attribute-based access control (ABAC)","Discretionary access control","Mandatory access control","Role-based access control"],e:"ABAC evaluates many attributes for fine-grained decisions."},
{d:4,q:"Which is the correct order of the incident response process?",a:["Preparation, Detection, Analysis, Containment, Eradication, Recovery, Lessons learned","Detection, Preparation, Recovery, Containment, Analysis, Eradication, Lessons learned","Containment, Detection, Preparation, Eradication, Recovery, Analysis, Lessons learned","Preparation, Containment, Detection, Recovery, Eradication, Analysis, Lessons learned"],e:"Prepare, find it, understand it, stop the spread, remove it, restore, then learn."},
{d:4,q:"An infected host is pulled off the network to stop the spread. Which IR phase is this?",a:["Containment","Eradication","Recovery","Preparation"],e:"Containment limits damage. Eradication removes the threat; recovery restores normal operation."},
{d:4,q:"When collecting evidence, what should be captured FIRST by order of volatility?",a:["CPU cache and RAM","Hard drive","Backup tapes","Remote logs"],e:"Most volatile first: registers/cache, RAM, swap/temp files, disk, remote logs, archives."},
{d:4,q:"A record of everyone who handled a piece of evidence, and when, is the:",a:["Chain of custody","Legal hold","Risk register","Change log"],e:"Chain of custody shows the evidence wasn't tampered with."},
{d:4,q:"Legal counsel orders that all data related to a lawsuit be preserved. This is a:",a:["Legal hold","Data retention policy","Chain of custody","Right to be forgotten"],e:"A legal hold suspends normal deletion for relevant data."},
{d:4,q:"Proactively searching the network for attackers who slipped past automated tools is:",a:["Threat hunting","Vulnerability scanning","A tabletop exercise","Patch management"],e:"Threat hunting assumes compromise and looks for hidden activity."},
{d:4,q:"Running a suspicious file in an isolated environment to watch what it does is:",a:["Sandboxing","Hardening","Fuzzing","Tokenization"],e:"A sandbox isolates execution so malware can't harm real systems."},
{d:4,q:"Which is the secure replacement for Telnet?",a:["SSH","FTP","HTTP","SNMPv1"],e:"SSH encrypts remote sessions; Telnet sends everything in clear text."},
{d:4,q:"Which SNMP version adds authentication and encryption?",a:["SNMPv3","SNMPv1","SNMPv2c","None of them"],e:"SNMPv3 supports authentication and encryption; v1/v2c use clear-text community strings."},
{d:4,q:"Which is a valid concern when adding a lot of security automation?",a:["Complexity and creating a single point of failure","It removes the need for staff","It guarantees no false positives","It removes the need for change management"],e:"Automation speeds response and enforces baselines, but adds complexity, cost, technical debt and possible single points of failure."},
{d:4,q:"Records of which IPs talked to which, how much and when (but not full contents) come from:",a:["NetFlow","Full packet capture","DLP","Group Policy"],e:"NetFlow gives metadata about traffic flows; packet captures contain the full content."},
{d:4,q:"Which centrally applies security settings to Windows domain computers?",a:["Group Policy","SELinux","SNMP","NetFlow"],e:"Group Policy pushes settings across an Active Directory domain. SELinux enforces mandatory access control on Linux."},
{d:4,q:"Blocking employees from even resolving known malicious domains is done with:",a:["DNS filtering","SPF","Port security","RAID"],e:"DNS filtering stops lookups of bad domains before a connection is made."},
{d:4,q:"After an incident, the team digs into why it happened so it won't happen again. This is:",a:["Root cause analysis","Containment","Threat hunting","A legal hold"],e:"Root cause analysis finds the underlying cause, not just the symptoms."},
{d:4,q:"Which is the strongest password guidance for users?",a:["Use long passphrases and a password manager","Change the password daily","Use the same complex password everywhere","Write it on a sticky note under the keyboard"],e:"Length beats complexity tricks; password managers let users have unique strong passwords."},
// ---------- Domain 5 ----------
{d:5,q:"Which is a mandatory, high-level statement of management's intent?",a:["Policy","Guideline","Procedure","Playbook"],e:"Policies set direction. Standards set mandatory specifics. Procedures give step-by-step instructions. Guidelines are recommendations."},
{d:5,q:"Which document is a recommendation rather than a requirement?",a:["Guideline","Standard","Policy","Procedure"],e:"Guidelines are optional best-practice advice."},
{d:5,q:"'Passwords must be at least 14 characters' versus 'Steps to reset a password' are, respectively, a:",a:["Standard and a procedure","Procedure and a policy","Guideline and a standard","Policy and a guideline"],e:"Standards set required specifics; procedures give step-by-step instructions."},
{d:5,q:"Employees agree to rules for using company computers and internet. This is the:",a:["Acceptable Use Policy (AUP)","SLA","MOU","NDA"],e:"An AUP defines allowed and forbidden use of company resources."},
{d:5,q:"A $200,000 server has an exposure factor of 25%. What's the SLE?",a:["$50,000","$25,000","$200,000","$800,000"],e:"SLE = Asset Value x Exposure Factor = 200,000 x 0.25 = $50,000."},
{d:5,q:"SLE is $50,000 and the event is expected once every 2 years (ARO 0.5). What's the ALE?",a:["$25,000","$100,000","$50,000","$12,500"],e:"ALE = SLE x ARO = 50,000 x 0.5 = $25,000."},
{d:5,q:"A laptop worth $2,000 is fully lost each time it's stolen, and 4 are stolen per year. What's the ALE?",a:["$8,000","$2,000","$500","$4,000"],e:"SLE = 2,000 x 100% = 2,000. ALE = 2,000 x 4 = $8,000."},
{d:5,q:"Buying cyber insurance is which risk strategy?",a:["Transfer","Avoid","Accept","Mitigate"],e:"Transferring shifts the financial impact to a third party."},
{d:5,q:"A company cancels a risky product launch to eliminate a risk entirely. This is:",a:["Avoid","Transfer","Accept","Mitigate"],e:"Avoidance stops the activity that creates the risk."},
{d:5,q:"Installing a firewall to reduce the likelihood of an attack is which risk strategy?",a:["Mitigate","Transfer","Accept","Avoid"],e:"Mitigation reduces likelihood or impact with controls."},
{d:5,q:"Risk that remains after controls are applied is:",a:["Residual risk","Inherent risk","Risk appetite","Risk exception"],e:"Inherent risk is before controls; residual is what's left after."},
{d:5,q:"A document tracking identified risks, their owners, likelihood, impact and status is a:",a:["Risk register","BIA","SOW","Chain of custody"],e:"The risk register is the central list of risks. Key risk indicators (KRIs) help monitor them."},
{d:5,q:"Rating risks as High / Medium / Low instead of in dollars is:",a:["Qualitative risk analysis","Quantitative risk analysis","An ALE calculation","A gap analysis"],e:"Qualitative uses categories; quantitative uses numbers like SLE and ALE."},
{d:5,q:"Which process identifies critical business functions and the impact of losing them?",a:["Business Impact Analysis (BIA)","Penetration test","Vulnerability scan","Code review"],e:"The BIA drives RTO/RPO decisions and recovery priorities."},
{d:5,q:"A contract clause letting the company inspect a vendor's security practices is a:",a:["Right-to-audit clause","Non-disclosure clause","Force majeure clause","Rules of engagement"],e:"A right-to-audit clause lets you verify a third party's controls."},
{d:5,q:"An agreement that defines uptime guarantees and response times for a service is a(n):",a:["SLA","NDA","MOU","BPA"],e:"Service Level Agreements set measurable performance commitments."},
{d:5,q:"A usually non-binding statement that two organizations intend to work together is a(n):",a:["MOU","SLA","SOW","MSA"],e:"A Memorandum of Understanding (or Agreement) states intent and is usually not legally binding."},
{d:5,q:"A contract with general terms for all future work, with each project's details defined later, is a(n):",a:["MSA","SOW","NDA","SLA"],e:"Master Service Agreement = umbrella terms. Statement of Work = specific deliverables for one project."},
{d:5,q:"An agreement between partners that covers sharing profits, losses and responsibilities is a(n):",a:["BPA","NDA","SLA","AUP"],e:"A Business Partners Agreement defines how partners operate together."},
{d:5,q:"Under privacy laws like GDPR, the organization that decides why and how personal data is processed is the:",a:["Data controller","Data processor","Data subject","Data custodian"],e:"The controller decides; the processor processes on its behalf; the subject is the person the data is about."},
{d:5,q:"The 'right to be forgotten' lets:",a:["Individuals ask for their personal data to be deleted","Companies delete audit logs","Vendors cancel contracts","Admins skip retention policies"],e:"Under GDPR, data subjects can have their data erased in certain cases."},
{d:5,q:"Who typically handles day-to-day protection of data, such as backups and applying access rules?",a:["Data custodian","Data owner","Data subject","Regulator"],e:"Owners are accountable for data; custodians/stewards carry out its protection day to day."},
{d:5,q:"A pen tester is given full network diagrams and source code. This is:",a:["Known environment testing","Unknown environment testing","Partially known testing","Passive reconnaissance"],e:"Known (white box), partially known (gray box), unknown (black box)."},
{d:5,q:"The document defining what a pen tester may test, when, and how is the:",a:["Rules of engagement","AUP","Risk register","BPA"],e:"Rules of engagement set scope, timing, methods and contacts for the test."},
{d:5,q:"Gathering information about a target from public websites without touching its systems is:",a:["Passive reconnaissance","Active reconnaissance","Exploitation","Lateral movement"],e:"Passive recon (like OSINT) avoids direct contact; active recon (like port scanning) touches the target."},
{d:5,q:"An independent firm reviews the company's controls and formally reports on them. This is:",a:["An external audit / attestation","An internal self-assessment","A tabletop exercise","A vulnerability scan"],e:"External audits give independent attestation of controls."},
{d:5,q:"Sending employees simulated phishing emails to measure and train them is part of:",a:["Security awareness training","Server penetration testing","Change management","Data retention"],e:"Phishing campaigns teach users to recognize and report attacks."},
{d:5,q:"Which is a possible consequence of failing to comply with regulations?",a:["Fines, sanctions and reputational damage","Lower insurance premiums","Automatic certification","Faster audits"],e:"Non-compliance can bring fines, sanctions, contract impacts, loss of license and reputational harm."},
{d:5,q:"Leadership's overall willingness to take on risk (e.g. 'conservative' or 'expansionary') is its:",a:["Risk appetite","Residual risk","Risk exception","ARO"],e:"Risk appetite describes how much risk leadership will accept to pursue goals."},
{d:5,q:"When an employee leaves, which process makes sure accounts are disabled and equipment returned?",a:["Offboarding","Onboarding","Provisioning","Federation"],e:"Offboarding removes access promptly to prevent misuse."},
{d:5,q:"Before signing with a new vendor, the company reviews its finances, security posture and history. This is:",a:["Due diligence","Rules of engagement","Attestation","Risk transfer"],e:"Vendor due diligence assesses third-party risk before entering a relationship."},
{d:5,q:"Making sure no single person can both create and approve payments is:",a:["Separation of duties","Least privilege","Job rotation","Mandatory vacation"],e:"Separation of duties prevents one person completing a sensitive task alone, reducing fraud."},
// ---------- Bonus: AI ----------
{d:6,q:"Hidden instructions in a document make an AI assistant ignore its rules and leak data. This is:",a:["Prompt injection","Data poisoning","Model inversion","SQL injection"],e:"Prompt injection manipulates an AI model through crafted input, typed directly or hidden in content it reads."},
{d:6,q:"Attackers slip mislabeled examples into a model's training data to change its behavior. This is:",a:["Data poisoning","Prompt injection","Hallucination","Model drift"],e:"Training-data poisoning corrupts what the model learns."},
{d:6,q:"Repeatedly querying a model to reconstruct sensitive data it was trained on is:",a:["Model inversion","Data poisoning","Sideloading","Smishing"],e:"Model inversion infers training data from outputs. Model extraction tries to copy the model itself."},
{d:6,q:"An AI confidently gives a false answer that sounds correct. This is called:",a:["Hallucination","Poisoning","Inversion","Drift"],e:"Hallucinations are fabricated outputs; verify AI output before acting on it."},
{d:6,q:"Employees paste confidential code into unapproved public AI chatbots. This risk is:",a:["Shadow AI and data leakage","Model inversion","Data poisoning","Evil twin"],e:"Like shadow IT, unapproved AI tools can leak sensitive data. Policies and approved tools help."},
{d:6,q:"A clerk gets a video call from what looks and sounds like the CFO approving a wire transfer, but it's synthetic. This is:",a:["Deepfake-enabled social engineering","A watering hole attack","A logic bomb","A replay attack"],e:"AI-generated voice and video make impersonation more convincing. Verify through a separate, known channel."},
{d:6,q:"Rules and filters that limit what an AI system will accept or output are called:",a:["Guardrails","Honeytokens","Salts","Bollards"],e:"Guardrails (input/output filtering, policies) constrain AI behavior."},
{d:6,q:"Giving an AI agent only the tools and data it needs for its task applies which principle?",a:["Least privilege","Implicit trust","Fail-open","Risk transfer"],e:"Least privilege applies to AI agents just as it does to users."},
{d:6,q:"A model's accuracy slowly worsens because real-world data has changed since training. This is:",a:["Model drift","Prompt injection","Data poisoning","Hallucination"],e:"Drift calls for monitoring and periodic retraining."}
];

